1	// gcec local check: every artifact `npm run regen` rewrites carries a `merge=ours`
2	// entry in .gitattributes. The rule this converts is RULES.md's regen bullet —
3	// the `ours` driver's file set is "kept in sync with `.gitattributes`" — and
4	// .gitattributes' own header states the mechanism: on a conflicting merge the
5	// driver keeps one side automatically, you rerun the generator, and there is
6	// nothing to resolve by hand.
7	//
8	// Why a check and not just prose: the set of regen artifacts GROWS ON ITS OWN.
9	// Requirement kinds are auto-discovered (dev/requirements/shared/kinds.js — "adding
10	// a kind is a self-contained folder drop"), so a new `image` kind starts committing
11	// baselines under dev/requirements/<kind>/cases/*.png with nobody editing a list
12	// anywhere. .gitattributes, meanwhile, names popup/ and icon/ literally. The new
13	// kind's PNGs are then off the driver, and nothing says so: every suite stays
14	// green, `npm run regen` keeps working, and the omission only surfaces later as a
15	// merge conflict on a BINARY file that git cannot 3-way merge at all — the one
16	// conflict a human genuinely cannot resolve, hit at the worst moment (mid-merge).
17	// That gap between an auto-discovered producer and a hand-kept list is exactly
18	// what a static scan is for.
19	//
20	// SCOPE, and how it divides with the canon: the canon's basics/generated-merge-driver
21	// rule already covers files whose name carries `GENERATED` (this repo's
22	// generic-coverage.baseline.GENERATED.json / generic-coverage.GENERATED.md). It
23	// matches that marker case-sensitively, so it sees neither this repo's
24	// lowercase-`.generated.` artifact (load-order.generated.json) nor the snapshot
25	// PNGs, which carry no marker in their names at all. This check takes exactly that
26	// remainder — the repo's own regen outputs the canon marker doesn't name — so the
27	// two never double-report the same file.
28	//
29	// Only the "artifact with no entry" direction is checked. A leftover entry for a
30	// renamed artifact is cosmetic (the renamed file trips this check under its new
31	// path), and matching globs against a file list would false-positive under a
32	// --changed run, where that list is narrowed. Under-reporting is the safe error.
33	//
34	// Local-pack check modules are dependency-free on purpose (see
35	// test-offline-list-sync.mjs's header): plain finding objects, no engine imports,
36	// so they also load under the repo's own `npm test` (pack.test.mjs).
37	const id = 'regen-artifacts-merge-ours';
38	const severity = 'blocking';
39	const doc = '.claudinite/local/packs/gcec/RULES.md';
40	const why =
41	  'a regen artifact off the `ours` driver hits a hand-resolved merge conflict — and the UI ' +
42	  'baselines are binary PNGs git cannot 3-way merge at all';
43	
44	// A UI-snapshot baseline: dev/requirements/<kind>/cases/<case>.png, for ANY kind,
45	// because kinds are auto-discovered and a new image kind must not need this check
46	// edited to be covered.
47	const CASE_SNAPSHOT = /^dev\/requirements\/[^/]+\/cases\/[^/]+\.png$/;
48	
49	// A generated artifact named with the lowercase `.generated.` convention. The
50	// uppercase GENERATED marker is the canon rule's half of the set, excluded here so
51	// one file never yields two findings.
52	function isLowercaseGenerated(file) {
53	  const base = file.split('/').pop();
54	  return /\.generated\./.test(base) && !base.includes('GENERATED');
55	}
56	
57	// .gitattributes patterns are gitignore-style: `*` and `?` do not cross a `/`,
58	// `**` does, and a pattern containing no `/` matches by basename at any depth.
59	function globToRe(glob) {
60	  let out = '';
61	  for (let i = 0; i < glob.length; i += 1) {
62	    const ch = glob[i];
63	    if (ch === '*') {
64	      if (glob[i + 1] === '*') {
65	        out += '.*';
66	        i += 1;
67	      } else {
68	        out += '[^/]*';
69	      }
70	      continue;
71	    }
72	    if (ch === '?') {
73	      out += '[^/]';
74	      continue;
75	    }
76	    out += ch.replace(/[.+^${}()|[\]\\]/, '\\$&');
77	  }
78	  return new RegExp(`^${out}$`);
79	}
80	
81	function oursPatterns(text) {
82	  return (text || '')
83	    .split('\n')
84	    .map((l) => l.trim())
85	    .filter((l) => l && !l.startsWith('#') && /\bmerge=ours\b/.test(l))
86	    .map((l) => l.split(/\s+/)[0].replace(/^\/+/, ''))
87	    .map((pattern) => ({ pattern, re: globToRe(pattern), byBasename: !pattern.includes('/') }));
88	}
89	
90	export default {
91	  id,
92	  severity,
93	  description: 'every `npm run regen` artifact has a merge=ours entry in .gitattributes',
94	  doc,
95	  why,
96	
97	  run(ctx) {
98	    // allFiles, not files: this rule reasons ABOUT generated artifacts, so it must
99	    // still see them if the repo ever marks them linguist-generated (which the
100	    // engine otherwise drops from ctx.files) — the same reason the canon's
101	    // generated-merge-driver reads allFiles. Falls back to ctx.files for a context
102	    // that doesn't draw the distinction.
103	    const all = ctx.allFiles || ctx.files || [];
104	    const artifacts = all.filter((f) => CASE_SNAPSHOT.test(f) || isLowercaseGenerated(f));
105	    if (!artifacts.length) return [];
106	
107	    const patterns = oursPatterns(ctx.read('.gitattributes'));
108	
109	    return artifacts
110	      .filter((file) => {
111	        const base = file.split('/').pop();
112	        return !patterns.some((p) => (p.byBasename ? p.re.test(base) : p.re.test(file)));
113	      })
114	      .map((file) => {
115	        // Suggest the shape the repo already uses: one line per snapshot DIRECTORY,
116	        // one line per generated file.
117	        const suggestion = CASE_SNAPSHOT.test(file)
118	          ? `${file.slice(0, file.lastIndexOf('/'))}/*.png`
119	          : file;
120	        return {
121	          rule: id,
122	          severity,
123	          file,
124	          line: null,
125	          what: `${file} is regenerated by \`npm run regen\` but has no merge=ours entry in .gitattributes`,
126	          why,
127	          fix: `add \`${suggestion} merge=ours\` to .gitattributes (beside the other regen artifacts), so a conflicting merge auto-resolves and you rerun the generator instead of hand-merging`,
128	          doc,
129	        };
130	      });
131	  },
132	};
133

1	// gcec local check: the shared extraction pipeline never names a site. The core
2	// generic extractor, the orchestrator, the registry and the shared helpers —
3	// everything under extension/event-extractors/ that is NOT custom/ — run on every
4	// page, so none of them may carry knowledge of one specific site. The rule this
5	// converts is RULES.md's "Architecture rules of the road": the generic extractor
6	// is the base layer of every extraction and "may never know about a specific
7	// site"; custom/ is the one place per-site knowledge lives (guarded from the
8	// other side by custom-sources-flat).
9	//
10	// Why a check and not just prose: a host-gated special case in shared code fails
11	// SILENTLY in the one place this repo automates a decision. The site it patches
12	// works, every suite stays green — and the generic-coverage gate then reports
13	// that site as gap-free, because the gap was hardcoded away rather than closed
14	// generically. RULES.md reads a no-gap site as "a candidate for deleting the
15	// per-site source and listing the host in supportedDomains", so the erosion
16	// doesn't just sit there: it feeds a wrong answer into the next decision, with
17	// nothing red anywhere. It also quietly ends the property the architecture is
18	// built to keep — adding a host is a single-file change.
19	//
20	// SCOPE, stated honestly: this catches the obvious carrier, a supported host
21	// named in shipped code. A site-specific hack keyed on something else (a
22	// selector only one site uses) is not detectable statically and stays the
23	// reader's job — which is why the architecture bullet in RULES.md stays whole
24	// beside this check rather than being deleted.
25	//
26	// The host list is READ from the repo, never hardcoded: extension/host-lists.json's
27	// `supportedDomains` is the one declaration of the hosts we claim (RULES.md:
28	// "Being supported is DECLARED"), so the check follows that list around instead
29	// of pinning a copy that would drift.
30	//
31	// COMMENTS ARE SKIPPED, deliberately. Naming the site where a generic pattern was
32	// observed is exactly how this codebase documents evidence — generic-extractor.js
33	// cites stubhub.com for a venue heuristic, derive-timezone.js cites eventer.co.il
34	// and visit.tel-aviv.gov.il, embedded-events.js cites livenation.de. Those are
35	// rationale, not site knowledge. Comments are blanked by a small scanner (not a
36	// regex) that tracks string literals, so a host inside a 'https://…' string is
37	// still code and still found.
38	//
39	// Local-pack check modules are dependency-free on purpose (see
40	// test-offline-list-sync.mjs's header): plain finding objects, no engine imports,
41	// so they also load under the repo's own `npm test` (pack.test.mjs).
42	const id = 'pipeline-site-agnostic';
43	const severity = 'blocking';
44	const doc = '.claudinite/local/packs/gcec/RULES.md';
45	const why =
46	  'the shared pipeline runs on every page — a host-gated special case there makes the ' +
47	  'generic-coverage gate report that site as gap-free when the gap was only hardcoded ' +
48	  'away, and every suite stays green while it happens';
49	
50	const DIR = 'extension/event-extractors/';
51	const CUSTOM_DIR = `${DIR}custom/`;
52	const HOST_LIST = 'extension/host-lists.json';
53	
54	// Blank every comment, keeping the file's exact length and line breaks so line
55	// numbers stay true. A hand-rolled scanner rather than a regex because `//`
56	// inside a string ('https://…') is not a comment and must not swallow the rest
57	// of the line — that is precisely where a host literal would hide.
58	function blankComments(src) {
59	  const out = [];
60	  let i = 0;
61	  const keep = (ch) => out.push(ch);
62	  const blank = (ch) => out.push(ch === '\n' ? '\n' : ' ');
63	  while (i < src.length) {
64	    const ch = src[i];
65	    const next = src[i + 1];
66	    if (ch === '/' && next === '/') {
67	      while (i < src.length && src[i] !== '\n') blank(src[i++]);
68	      continue;
69	    }
70	    if (ch === '/' && next === '*') {
71	      blank(src[i++]);
72	      blank(src[i++]);
73	      while (i < src.length && !(src[i] === '*' && src[i + 1] === '/')) blank(src[i++]);
74	      if (i < src.length) {
75	        blank(src[i++]);
76	        blank(src[i++]);
77	      }
78	      continue;
79	    }
80	    if (ch === '"' || ch === "'" || ch === '`') {
81	      const quote = ch;
82	      keep(src[i++]);
83	      while (i < src.length) {
84	        if (src[i] === '\\') {
85	          keep(src[i++]);
86	          if (i < src.length) keep(src[i++]);
87	          continue;
88	        }
89	        if (src[i] === quote) {
90	          keep(src[i++]);
91	          break;
92	        }
93	        keep(src[i++]);
94	      }
95	      continue;
96	    }
97	    keep(src[i++]);
98	  }
99	  return out.join('');
100	}
101	
102	// A host counts only as a whole label run: "notstubhub.com" is not stubhub.com,
103	// and inside "visit.tel-aviv.gov.il" the shorter "tel-aviv.gov.il" doesn't match
104	// on its own (the longer entry in the list does, and is reported instead).
105	const HOST_CHAR = /[A-Za-z0-9.-]/;
106	function namesHost(line, host) {
107	  let from = 0;
108	  for (;;) {
109	    const at = line.indexOf(host, from);
110	    if (at === -1) return false;
111	    const before = at === 0 ? '' : line[at - 1];
112	    const afterIndex = at + host.length;
113	    const after = afterIndex >= line.length ? '' : line[afterIndex];
114	    if (!HOST_CHAR.test(before) && !HOST_CHAR.test(after)) return true;
115	    from = at + 1;
116	  }
117	}
118	
119	export default {
120	  id,
121	  severity,
122	  description: "the shared extraction pipeline names no supported site — per-site knowledge lives only in custom/",
123	  doc,
124	  why,
125	
126	  run(ctx) {
127	    const raw = ctx.read(HOST_LIST);
128	    if (!raw) return [];
129	    let hosts;
130	    try {
131	      hosts = JSON.parse(raw).supportedDomains;
132	    } catch {
133	      return []; // a malformed host list breaks the extension's own tests first
134	    }
135	    if (!Array.isArray(hosts) || !hosts.length) return [];
136	    // Longest first, so a finding names visit.tel-aviv.gov.il rather than the
137	    // shorter entry it contains.
138	    const ordered = [...hosts].filter((h) => typeof h === 'string' && h).sort((a, b) => b.length - a.length);
139	
140	    const findings = [];
141	    // ctx.files is the whole repo under the engine's default `all` sweep; a
142	    // --changed run narrows it, which only ever under-reports.
143	    for (const file of ctx.files) {
144	      if (!file.startsWith(DIR) || file.startsWith(CUSTOM_DIR)) continue;
145	      if (!file.endsWith('.js')) continue;
146	      const src = ctx.read(file);
147	      if (!src) continue;
148	      const lines = blankComments(src).split('\n');
149	      lines.forEach((line, index) => {
150	        const host = ordered.find((h) => namesHost(line, h));
151	        if (!host) return;
152	        findings.push({
153	          rule: id,
154	          severity,
155	          file,
156	          line: index + 1,
157	          what: `${file} names the supported site ${host} in shipped code`,
158	          why,
159	          fix:
160	            `move the ${host}-specific handling into extension/event-extractors/custom/<site>.js ` +
161	            '(the one extensibility point), or generalize it so the pipeline reads what the page ' +
162	            'says about itself with no host in the condition — citing a site in a COMMENT as ' +
163	            'evidence for a generic rule is fine and is not what this flags',
164	          doc,
165	        });
166	      });
167	    }
168	    return findings;
169	  },
170	};
171

1	// Red-first fixture tests for the gcec pack's checks, runnable by this repo's own
2	// `npm test` (no imports from the gitignored .claudinite mount — see the check
3	// module's header). Each rule is shown firing on a violating fixture and staying
4	// quiet on a clean one.
5	import test from 'node:test';
6	import assert from 'node:assert/strict';
7	import testOfflineListSync from './test-offline-list-sync.mjs';
8	import customSourcesFlat from './custom-sources-flat.mjs';
9	import npmTestGlobCoverage from './npm-test-glob-coverage.mjs';
10	import pipelineSiteAgnostic from './pipeline-site-agnostic.mjs';
11	import regenArtifactsMergeOurs from './regen-artifacts-merge-ours.mjs';
12	
13	function ctx({ files = [], pkg }) {
14	  const disk = new Set([...files, 'package.json']);
15	  return {
16	    files,
17	    read: (p) => (p === 'package.json' ? JSON.stringify(pkg) : null),
18	    exists: (p) => disk.has(p),
19	  };
20	}
21	
22	const pkgWith = (offline) => ({ scripts: { 'test:offline': `node --test ${offline.join(' ')}` } });
23	
24	test('test-offline-list-sync: fires when a mirror test is missing from the list', () => {
25	  const findings = testOfflineListSync.run(
26	    ctx({
27	      files: ['extension-test/a.test.js', 'extension-test/b.test.js'],
28	      pkg: pkgWith(['extension-test/a.test.js']),
29	    }),
30	  );
31	  assert.equal(findings.length, 1);
32	  assert.match(findings[0].what, /missing extension-test\/b\.test\.js/);
33	  assert.equal(findings[0].severity, 'blocking');
34	});
35	
36	test('test-offline-list-sync: fires when the list names a file that does not exist', () => {
37	  const findings = testOfflineListSync.run(
38	    ctx({
39	      files: ['extension-test/a.test.js'],
40	      pkg: pkgWith(['extension-test/a.test.js', 'extension-test/gone.test.js']),
41	    }),
42	  );
43	  assert.equal(findings.length, 1);
44	  assert.match(findings[0].what, /extension-test\/gone\.test\.js, which does not exist/);
45	});
46	
47	test('test-offline-list-sync: quiet when list and tree agree (non-mirror entries ignored)', () => {
48	  const findings = testOfflineListSync.run(
49	    ctx({
50	      files: ['extension-test/a.test.js', 'dev/build/test/other.test.js'],
51	      pkg: pkgWith(['extension-test/a.test.js', 'dev/build/release/shipping-files.test.js']),
52	    }),
53	  );
54	  assert.deepEqual(findings, []);
55	});
56	
57	test('test-offline-list-sync: quiet when package.json has no test:offline script', () => {
58	  const findings = testOfflineListSync.run(
59	    ctx({ files: ['extension-test/a.test.js'], pkg: { scripts: {} } }),
60	  );
61	  assert.deepEqual(findings, []);
62	});
63	
64	// A context whose files ARE the keys of a path → content map, for the rules that
65	// read file text rather than package.json.
66	const treeCtx = (tree) => ({
67	  files: Object.keys(tree),
68	  read: (p) => (p in tree ? tree[p] : null),
69	  exists: (p) => p in tree,
70	});
71	
72	test('custom-sources-flat: fires on a subdirectory, a non-source file, and a pipeline file in custom/', () => {
73	  const findings = customSourcesFlat.run(
74	    treeCtx({
75	      'extension/event-extractors/custom/barby.js': '',
76	      'extension/event-extractors/custom/shared/util.js': '',
77	      'extension/event-extractors/custom/README.md': '',
78	      'extension/event-extractors/custom/generic-extractor.js': '',
79	    }),
80	  );
81	  assert.equal(findings.length, 3);
82	  assert.match(findings[0].what, /sits in a subdirectory/);
83	  assert.match(findings[1].what, /is not a per-site source/);
84	  assert.match(findings[2].what, /is a pipeline file/);
85	  assert.ok(findings.every((f) => f.severity === 'blocking'));
86	});
87	
88	test('custom-sources-flat: quiet on a flat tree of per-site sources beside the pipeline', () => {
89	  const findings = customSourcesFlat.run(
90	    treeCtx({
91	      'extension/event-extractors/custom/barby.js': '',
92	      'extension/event-extractors/custom/tel-aviv.js': '',
93	      'extension/event-extractors/generic-extractor.js': '',
94	      'extension/event-extractors/registry.js': '',
95	      'extension/event-extractors/helpers/dates.js': '',
96	      'extension/event-extractors/load-order.generated.json': '',
97	    }),
98	  );
99	  assert.deepEqual(findings, []);
100	});
101	
102	// npm-test-glob-coverage reads package.json's `test` (and `test:e2e`) scripts, so its
103	// fixtures pair a file list with a scripts object — the real shape of both scripts,
104	// quoted globs included.
105	const globCtx = (files, scripts) =>
106	  ctx({ files, pkg: { scripts } });
107	
108	const SCRIPTS = {
109	  test: 'node --disable-warning=X --test "extension-test/**/*.test.js" "dev/build/test/**/*.test.js" ".claudinite/local/packs/**/*.test.mjs" "dev/requirements/logic/**/*.test.js" dev/requirements/requirements-coverage.test.js',
110	  'test:e2e': 'node --test "dev/requirements/heavy/**/*.test.js"',
111	};
112	
113	test('npm-test-glob-coverage: fires on a test file no `test` pattern reaches', () => {
