// gcec local task: generic-extractor-improvements — the weekly attempt to make the GENERIC
// generic extractor recover more of what the dedicated per-site sources get
// (per-project-scheduling DESIGN §6). Worker: task.md. Most runs correctly change
// nothing — the coverage gate already banks every prior win — so a forced or fake
// win is worse than none; no win → no branch, no PR.
//
// Self-contained (imports nothing): the whole contract is this default export.

export default {
  id: 'generic-extractor-improvements',
  frequency: 'weekly',            // fires on the repo's weekly anchor day/hour
  precondition_signals: ['commits'],
  agent_model: 'opus',                 // closing a real generic-extractor gap is heavy judgment
  expected_outcome: 'open-pr',            // a generic win lands as a PR the owner reviews; never auto-merged

  agent_instructions: 'task.md',
  // The best-effort run bound the executor surfaces into the subagent's brief
  // (agent-preprocessing DESIGN §2, §6): "fail after N minutes". Very generous —
  // this is an OPEN-ENDED judgment loop (hypothesize → edit → the network-bound
  // `test:live` → compare, iterated), not a predictable mechanical run, so the
  // bound is extreme runaway protection, not a scheduling knob. No deterministic
  // pre-step is split into agent_preprocessing here: the baseline the agent picks
  // targets from is measured by `test:live` on a fresh clone and must be SEEN by
  // the agent, and preprocessing has no code→agent data channel (DESIGN §3), so
  // the whole task stays a single agentic stage.
  agent_execution_timeout: 5400,

  // This is the old preconditions.sh, moved into code over the `commits` signal
  // (DESIGN §6): the result is a pure function of the source, and most weeks nothing
  // meaningful lands, so a run over unchanged code would re-derive last week's
  // answer while burning a full model run. `commits.substantiveChange` is exactly
  // the shell's "a commit touched real source, not only docs/GENERATED" notion,
  // windowed to whatever's landed since the last successful run. When in doubt
  // the week still runs: a run that finds nothing is cheap and makes no PR; a
  // too-clever skip that misses a real opportunity is not.
  precondition(signals) {
    const commits = signals.commits ?? {};
    if (!commits.substantiveChange) {
      return { run: false, reason: 'no meaningful code change in the window (idle, or docs/generated churn only)' };
    }
    const shas = (commits.list ?? []).filter((c) => c.substantive).map((c) => c.sha.slice(0, 7));
    return {
      run: true,
      reason: `${shas.length} meaningful commit(s) in the window`,
      context: [
        `Scope: the ${shas.length} substantive commit(s) in the window — ${shas.join(', ')}.`,
        'Most runs correctly change nothing — only open a PR on a real generic-extractor win that clears the coverage gate; a forced or fake win is worse than none.',
      ],
    };
  },
};

// Validation for the "Required explicit support for Extractors" requirements
// (requirements.md §11): each supported host, run against a REAL cached page,
// must be recognized as supported and produce a COMPLETE event (title + location
// + start). One `kind: "extractor"` case per supported host declares the host,
// the source file that claims it, and the cached page to validate against; this
// test is the executable side of those leaves — the analogue of
// events-view-actions.test.js for the `kind: "behavior"` leaves.
//
// Support is DECLARED, not derived: a host is supported because it is listed in
// extension/host-lists.json's `supportedDomains` (the same list the toolbar
// icon and the popup read), and this test asserts that declaration alongside the
// extraction. A case's `source` names whichever file the support rests on — a
// per-site event-extractors/custom/<site>.js, or the core
// event-extractors/generic-extractor.js for a host it covers on its own, with no
// per-site file. The assertions are the same either way: support is support.
//
// It asserts only RECOGNITION + COMPLETENESS, not exact field values: the precise
// extracted values stay pinned by the reviewed per-page cases in
// dev/requirements/extractor/expected/*.json (live.test.js). A `tbd`
